{
  "root": "main",
  "state": {
    "itinerary": [
      { "day": "Oct 8", "focus": "Higashiyama temples", "majorActivities": "Kiyomizu-dera; Sannenzaka/Ninenzaka stroll", "slowAfternoon": "Tea break + early check-in/rest", "transport": "USD 8–12", "spend": "USD 110–150" },
      { "day": "Oct 9", "focus": "Arashiyama nature", "majorActivities": "Bamboo Grove; Iwatayama Monkey Park or riverside walk", "slowAfternoon": "Café time by the river", "transport": "USD 12–18", "spend": "USD 120–170" },
      { "day": "Oct 10", "focus": "Nishiki + central Kyoto", "majorActivities": "Nishiki Market; Kyoto Imperial Palace or nearby gardens", "slowAfternoon": "Long lunch + hotel downtime", "transport": "USD 6–10", "spend": "USD 90–140" },
      { "day": "Oct 11", "focus": "Fushimi + sake area", "majorActivities": "Fushimi Inari early hike; Fushimi sake district", "slowAfternoon": "Slow lunch + onsen/café afternoon", "transport": "USD 10–16", "spend": "USD 110–160" },
      { "day": "Oct 12", "focus": "Northern Kyoto", "majorActivities": "Ryoan-ji; Kinkaku-ji or Philosopher’s Path if preferred", "slowAfternoon": "Final shopping + relaxed café stop", "transport": "USD 8–14", "spend": "USD 100–150" }
    ],
    "budget": [
      { "category": "Lodging", "total": "USD 650–850", "notes": "Mid-range hotel or ryokan-like stay, 4 nights" },
      { "category": "Local transport", "total": "USD 45–70", "notes": "Subway, bus, occasional taxi, train" },
      { "category": "Food and drinks", "total": "USD 420–560", "notes": "Mix of market meals, cafés, and dinners" },
      { "category": "Admissions", "total": "USD 90–160", "notes": "Temple entries, Monkey Park, garden fees" },
      { "category": "Shopping", "total": "USD 80–140", "notes": "Souvenirs, tea, sweets" },
      { "category": "Buffer", "total": "USD 120–200", "notes": "Rainy-day taxi, extra meal" }
    ]
  },
  "elements": {
    "main": { "type": "Stack", "props": { "direction": "vertical", "gap": "md", "padding": 16 }, "children": ["title", "summary", "itineraryTable", "budgetTable", "actions"] },
    "title": { "type": "Text", "props": { "text": "Kyoto 5-Day Trip Plan", "variant": "h1" }, "children": [] },
    "summary": { "type": "Text", "props": { "text": "A temple-forward, relaxed 5-day plan for 2 adults (Oct 8–12) with a USD 1,800 local budget." }, "children": [] },
    "itineraryTable": { "type": "Table", "props": { "title": "Itinerary Overview", "domain": "schedule", "preferredPresentation": "cards", "primaryColumn": "day", "statePath": "/itinerary", "columns": [{ "key": "day", "label": "Day" }, { "key": "focus", "label": "Focus" }, { "key": "majorActivities", "label": "Activities" }, { "key": "slowAfternoon", "label": "Slow Afternoon" }] }, "children": [] },
    "budgetTable": { "type": "Table", "props": { "title": "Budget Breakdown", "domain": "generic", "preferredPresentation": "table", "statePath": "/budget", "columns": [{ "key": "category", "label": "Category" }, { "key": "total", "label": "Total" }, { "key": "notes", "label": "Notes" }] }, "children": [] },
    "actions": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["btn1", "btn2", "btn3"] },
    "btn1": { "type": "Button", "props": { "label": "Kyoto transit guide", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.jrpass.com/area/kyoto" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Temple hours and fees", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.japan-guide.com/e/e2158.html" } } } }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Kyoto market guide", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.japan-guide.com/e/e3931.html" } } } }, "children": [] }
  }
}
